<?php
require_once __DIR__ . '/_init.php'; mc_admin_require_login(); $c=mc_admin_credentials(); $error='';
if($_SERVER['REQUEST_METHOD']==='POST'){mc_csrf_check();$current=(string)($_POST['current_password']??'');$newUser=trim((string)($_POST['username']??''));$newPass=(string)($_POST['new_password']??'');$newPass2=(string)($_POST['new_password2']??'');if(!password_verify($current,(string)$c['passwordHash']))$error='La contraseña actual no es correcta.';elseif(strlen($newUser)<3)$error='El usuario debe tener al menos 3 caracteres.';elseif($newPass!==''&&strlen($newPass)<8)$error='La nueva contraseña debe tener al menos 8 caracteres.';elseif($newPass!==$newPass2)$error='Las nuevas contraseñas no coinciden.';else{$hash=$newPass!==''?password_hash($newPass,PASSWORD_BCRYPT):$c['passwordHash'];if(mc_write_admin_credentials($newUser,$hash)){mc_flash('success','Credenciales actualizadas.');header('Location: perfil.php');exit;}else$error='No se pudo escribir admin/config/admin_credentials.js.';}}
mc_admin_header('Usuario y contraseña');?><?php if($error):?><div class="alert error"><?=mc_h($error)?></div><?php endif;?><section class="card"><h2>Cambiar acceso administrativo</h2><form method="post"><input type="hidden" name="csrf" value="<?=mc_h(mc_csrf_token())?>"><div class="form-grid"><div class="field"><label>Usuario</label><input name="username" required value="<?=mc_h($c['username'])?>"></div><div></div><div class="field"><label>Contraseña actual</label><input type="password" name="current_password" required autocomplete="current-password"></div><div></div><div class="field"><label>Nueva contraseña (opcional)</label><input type="password" name="new_password" minlength="8" autocomplete="new-password"></div><div class="field"><label>Repetir nueva contraseña</label><input type="password" name="new_password2" minlength="8" autocomplete="new-password"></div></div><button class="btn primary" style="margin-top:16px">Actualizar credenciales</button></form><div class="notice">Las credenciales continúan guardándose en <b>admin/config/admin_credentials.js</b>. La contraseña queda como hash bcrypt.</div></section><?php mc_admin_footer();?>